import{_ as o,o as r,c as e,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"MCP-подключения","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/mcp.md","filePath":"ru/guides/mcp.md","lastUpdated":1792323081000}'),s={name:"ru/guides/mcp.md"};function n(d,t,l,i,h,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="mcp-подключения" tabindex="-1">MCP-подключения <a class="header-anchor" href="#mcp-подключения" aria-label="Permalink to &quot;MCP-подключения&quot;">​</a></h1><p>Memoh полностью поддерживает <strong>Model Context Protocol (MCP)</strong> и позволяет подключать Bot к внешним сервисам инструментов и поставщикам контекста.</p><h2 id="идея-расширение-возможностеи-bot" tabindex="-1">Идея: расширение возможностей Bot <a class="header-anchor" href="#идея-расширение-возможностеи-bot" aria-label="Permalink to &quot;Идея: расширение возможностей Bot&quot;">​</a></h2><p>MCP даёт стандартизированный способ открыть Bot доступ к внешним источникам данных и инструментам. У каждого Bot может быть собственный независимый набор MCP-подключений.</p><p>Подключения можно настраивать вручную на вкладке <strong>MCP</strong> или начать с готового шаблона в <strong><a href="./supermarket.html">Supermarket</a></strong>, а затем просмотреть предзаполненный черновик в редакторе Bot.</p><hr><h2 id="типы-подключении" tabindex="-1">Типы подключений <a class="header-anchor" href="#типы-подключении" aria-label="Permalink to &quot;Типы подключений&quot;">​</a></h2><p>MCP-подключения настраиваются на вкладке <strong>MCP</strong> страницы Bot.</p><h3 id="_1-stdio-локальныи-процесс" tabindex="-1">1. Stdio (локальный процесс) <a class="header-anchor" href="#_1-stdio-локальныи-процесс" aria-label="Permalink to &quot;1. Stdio (локальный процесс)&quot;">​</a></h3><p>Подключение этого типа выполняет локальную команду внутри контейнера Bot и общается через стандартный ввод/вывод.</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Command</strong></td><td>Исполняемый файл (например, <code>npx</code>, <code>python3</code>).</td></tr><tr><td><strong>Arguments</strong></td><td>Список аргументов командной строки (например, <code>-y</code>, <code>@modelcontextprotocol/server-filesystem</code>, <code>/opt/memoh/data</code>).</td></tr><tr><td><strong>Env</strong></td><td>Пары «ключ — значение» для переменных окружения.</td></tr><tr><td><strong>CWD</strong></td><td>Рабочий каталог процесса.</td></tr></tbody></table><h3 id="_2-remote-http-sse" tabindex="-1">2. Remote (HTTP/SSE) <a class="header-anchor" href="#_2-remote-http-sse" aria-label="Permalink to &quot;2. Remote (HTTP/SSE)&quot;">​</a></h3><p>Подключение этого типа соединяется с удалённым MCP-сервером по сети.</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>Конечная точка удалённого MCP-сервера.</td></tr><tr><td><strong>Headers</strong></td><td>Пользовательские HTTP-заголовки (например, для аутентификации).</td></tr><tr><td><strong>Transport</strong></td><td>Выбор между <code>http</code> и <code>sse</code> (Server-Sent Events).</td></tr></tbody></table><hr><h2 id="аутентификация-по-oauth" tabindex="-1">Аутентификация по OAuth <a class="header-anchor" href="#аутентификация-по-oauth" aria-label="Permalink to &quot;Аутентификация по OAuth&quot;">​</a></h2><p>Некоторым MCP-серверам нужна аутентификация на основе OAuth. Memoh поддерживает полный MCP-поток OAuth:</p><ol><li>Нажмите кнопку <strong>OAuth</strong> на подключении, требующем аутентификации.</li><li>Memoh автоматически <strong>обнаружит</strong> OAuth-конфигурацию сервера.</li><li>Нажмите <strong>Authorize</strong>, чтобы открыть страницу авторизации поставщика.</li><li>После выдачи доступа вы будете перенаправлены обратно в Memoh.</li><li>Токен <strong>обменивается</strong> и безопасно сохраняется для этого подключения.</li></ol><p>Также можно:</p><ul><li><strong>Check status</strong> — посмотреть текущее состояние OAuth-токена.</li><li><strong>Revoke</strong> — удалить сохранённый OAuth-токен.</li></ul><hr><h2 id="операции" tabindex="-1">Операции <a class="header-anchor" href="#операции" aria-label="Permalink to &quot;Операции&quot;">​</a></h2><ul><li><strong>Add Connection</strong>: нажмите <strong>Add</strong>, выберите тип и заполните конфигурацию.</li><li><strong>Import JSON</strong>: кнопка <strong>Import</strong> быстро добавляет несколько подключений из стандартного JSON-файла конфигурации <code>mcpServers</code>.</li><li><strong>Export</strong>: экспорт конфигураций подключений в JSON-файл для резервной копии или обмена.</li><li><strong>Toggle Active</strong>: включение и выключение отдельных подключений без удаления.</li><li><strong>Search</strong>: быстрый поиск подключения по имени или ID.</li><li><strong>Batch Delete</strong>: выбор нескольких подключений и удаление их разом.</li></ul><hr><h2 id="обнаружение-инструментов" tabindex="-1">Обнаружение инструментов <a class="header-anchor" href="#обнаружение-инструментов" aria-label="Permalink to &quot;Обнаружение инструментов&quot;">​</a></h2><p>Как только MCP-подключение становится активным, Memoh автоматически обнаруживает инструменты, которые предоставляет сервер. Вы можете:</p><ol><li>Открыть подключение, чтобы посмотреть его детали.</li><li>В разделе <strong>Tools</strong> увидеть все доступные инструменты с их именами и описаниями.</li><li>Bot будет сам использовать эти инструменты в разговорах, когда это уместно.</li></ol><p>Кнопкой <strong>Probe</strong> можно вручную обновить список инструментов с сервера.</p><hr><h2 id="взаимодеиствие-с-bot" tabindex="-1">Взаимодействие с Bot <a class="header-anchor" href="#взаимодеиствие-с-bot" aria-label="Permalink to &quot;Взаимодействие с Bot&quot;">​</a></h2><p>Когда MCP-подключение активно, Bot автоматически:</p><ul><li>обнаруживает инструменты и ресурсы, предоставляемые MCP-сервером;</li><li>использует эти инструменты для выполнения задач по запросу пользователя;</li><li>включает контекст, полученный от MCP-сервера, в процесс рассуждения.</li></ul>',32)])])}const u=o(s,[["render",n]]);export{p as __pageData,u as default};
